package com.bank.mask;

import java.util.logging.*;

public class ReduceDemo {
    private static final Logger log = Logger.getLogger("Mask");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        MaskService service = new MaskService();
        log.info(() -> "reduce : '" + service.repeatWithReduce("a", 5) + "'");   // aaaaa
        log.info(() -> "joining: '" + service.repeatWithJoining("a", 5) + "'");  // aaaaa (better)
    }
}

// ─── Would be in service/MaskService.java ───
class MaskService {
    // the question's expression, generalised: 5 copies of "a" reduced by concat
    String repeatWithReduce(String ch, int count) {
        return java.util.stream.IntStream.range(0, count)  // 0..4 → 5 values (exclusive end)
            .mapToObj(i -> ch)                              // each → "a"
            .reduce("", (a, b) -> a + b);                   // identity "" + concat → "aaaaa"
    }

    // preferred: joining uses StringBuilder internally (no quadratic concat)
    String repeatWithJoining(String ch, int count) {
        return java.util.stream.IntStream.range(0, count)
            .mapToObj(i -> ch)
            .collect(java.util.stream.Collectors.joining());
    }
}
